WordHunterWoW_ENDesc_Item[209057] = "Use: Install into a harvest reaper prototype."
WordHunterWoW_ENDesc_Item[209058] = "Use: Combine spare reaper parts with an elemental core to create a prototype engine."
WordHunterWoW_ENDesc_Item[209059] = "Use: Place as bait near a coyote dwelling"
