WordHunterWoW_ENDesc_Item[209525] = "Chance on hit: Sends a shadowy bolt at the enemy causing 30 Shadow damage."
WordHunterWoW_ENDesc_Item[209526] = "Chance on hit: Sends a shadowy bolt at the enemy causing 30 Shadow damage."
