WordHunterWoW_ENDesc_Item[209562] = "Chance on hit: Splash the target with ancient corrosive poison that deals 20 Nature damage every 3 sec and lowers the target's armor by 150 for 15 sec."
WordHunterWoW_ENDesc_Item[209570] = "Equip: Increases damage and healing done by magical spells and effects by up to 7."
