WordHunterWoW_ENDesc_Item[209579] = "Chance on hit: Discharge a mote of thunder dealing 15 Nature damage."
WordHunterWoW_ENDesc_Item[209580] = "Chance on hit: Blast a gust of wind dealing 15 Nature damage."
