WordHunterWoW_ENDesc_Item[211787] = "Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?"
WordHunterWoW_ENDesc_Item[211789] = "Equip: +24 Attack Power."
WordHunterWoW_ENDesc_Item[211800] = "Use: Brings a dead player back to life with 15% of their health and mana.  Cannot be used when in combat. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[211815] = "Use: Increases all damage and healing done by 5% for 2 hrs. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[211816] = "Use: Increases all damage and healing done by 5% for 2 hrs. (1 Sec Cooldown)"
